import {canvas,renderDocument,maskCanvas} from './renderer.js';
import {downloadBlob} from './storage.js';
import {localRuntime,localRequest} from './local-runtime.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createSkinResearch(api){
 function open(){
  const runtime=localRuntime();let mounted=true,busy=false,controller=null,result=null,preview=null;
  const note=s=>{if(mounted)$('#skin-research-status').textContent=s;};
  function prepare(){const d=api.doc();if(!d?.selection)throw Error('Khoanh vùng da trên canvas trước khi mở công cụ.');const scale=Math.min(1,1024/Math.max(d.width,d.height)),source=renderDocument(d,api.assets,{scale}),mask=maskCanvas(d,d.selection,scale,api.assets),pixels=mask.getContext('2d').getImageData(0,0,mask.width,mask.height).data;let l=mask.width,t=mask.height,r=0,b=0,count=0;for(let y=0;y<mask.height;y++)for(let x=0;x<mask.width;x++)if(pixels[(y*mask.width+x)*4+3]>127){l=Math.min(l,x);r=Math.max(r,x+1);t=Math.min(t,y);b=Math.max(b,y+1);count++;}if(count<64||r-l<64||b-t<64)throw Error('Vùng chọn cần ít nhất 64 × 64 pixel ở bản xử lý.');const c=canvas(r-l,b-t),x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(source,l,t,c.width,c.height,0,0,c.width,c.height);return c;}
  function show(){const root=$('#skin-research-results');if(!result){root.innerHTML='';return;}root.innerHTML=`<div class="precision-note"><strong>${result.abstained?'Chưa đủ cơ sở để phân loại':'Xếp hạng nhãn nghiên cứu · chưa kiểm định'}</strong><p>${(result.reasons||[]).map(esc).join(' ')||'Đây là tương đồng ảnh–mô tả, không phải chẩn đoán hay xác suất mắc bệnh.'}</p></div>${(result.candidates||[]).map((c,i)=>`<div class="surface-feature"><span><strong>${i+1}. ${esc(c.label)}</strong><small>Điểm cosine · không phải % mắc bệnh</small></span><b>${Number(c.score).toFixed(3)}</b></div>`).join('')}<p class="gen-size-note">${esc(result.model?.id||'Chưa chạy model')} · ${esc(result.model?.tensorDevice||'Chưa có bằng chứng thiết bị')}<br>Kiểm chứng lâm sàng: chưa thực hiện.</p>`;$('#skin-research-export').disabled=false;}
  async function run(){if(busy||!runtime||!preview)return;busy=true;$('#skin-research-run').disabled=true;controller=new AbortController();try{note('Đang chạy model local trên CUDA. Lần đầu có thể mất thời gian nạp trọng số…');result=await localRequest('/api/skin-classify',{method:'POST',body:{image:preview.toDataURL('image/png')},signal:AbortSignal.any([controller.signal,AbortSignal.timeout(180000)])});if(!mounted)return;if(result.validated!==false||result.scoreType!=='cosine_similarity'||!Array.isArray(result.candidates))throw Error('Kết quả không đúng hợp đồng nghiên cứu.');show();note('Đã nhận kết quả nghiên cứu. Nguồn ảnh và vùng chọn chưa bị thay đổi.');}catch(e){if(e.name!=='AbortError')note(e.message);}finally{busy=false;if(mounted)$('#skin-research-run').disabled=!preview||!runtime;}}
  api.showModal('Phân loại da · nghiên cứu','MedSigLIP local · kết quả phải được chuyên gia đánh giá',`<div class="precision-layout"><div><div class="gen-preview-wrap"><canvas id="skin-research-preview" aria-label="Vùng da sẽ được gửi tới dịch vụ local trên máy của bạn"></canvas></div><p id="skin-research-status" class="advanced-status" role="status"></p><div id="skin-research-results"></div></div><div class="precision-controls"><span class="live-pill">RESEARCH · NOT DIAGNOSIS</span><h3>Đánh giá một vùng da.</h3><p class="lab-explanation">Khoanh vùng trên canvas. Model so ảnh với nhóm mô tả mụn, vảy nến, chàm, rosacea, bạch biến và một số dấu vết ngoại quan. Không có xác suất bệnh đã hiệu chỉnh, xét nghiệm hay kiểm chứng lâm sàng.</p><p class="precision-note">Kết quả chỉ phục vụ nghiên cứu, có thể nhầm hoặc bỏ sót bệnh ngoài nhóm nhãn. Không dùng để chẩn đoán, quyết định điều trị hoặc tự động xóa vùng ảnh. Nguồn ảnh được giữ nguyên.</p><button class="button primary" id="skin-research-run" disabled>Chạy nghiên cứu trên máy tôi</button><button class="button" id="skin-research-export" disabled>Tải kết quả JSON</button><a class="button" href="assets/luma-local-gpu-kit.zip" download>Tải bộ Windows + NVIDIA</a><details class="advanced-details"><summary>Cài model local</summary><p>Cài bộ GPU với tùy chọn Research. Tải google/medsiglip-448 từ nguồn Google sau khi tự xem và chấp nhận điều khoản, rồi chạy Start-Luma.ps1 -SkinModelDir với thư mục đó. Ứng dụng không tự tải trọng số hoặc nhận token Hugging Face.</p><p>Model chưa được huấn luyện / kiểm định cho mục đích chẩn đoán trong Luma. Điểm hiển thị là cosine, không phải độ tin cậy lâm sàng. Cơ chế từ chối chỉ là ngưỡng kỹ thuật, chưa có OOD detector được kiểm định.</p><a href="https://developers.google.com/health-ai-developer-foundations/medsiglip/model-card" target="_blank" rel="noopener">Model card Google ↗</a></details></div></div>`,[{label:'Đóng',run:()=>api.closeModal(true)}],()=>{
   try{preview=prepare();const c=$('#skin-research-preview');c.width=preview.width;c.height=preview.height;c.getContext('2d').drawImage(preview,0,0);note(runtime?'Vùng chọn sẽ chỉ gửi tới dịch vụ local của phiên này.':'Cần mở bản local bằng Start-Luma.ps1. Bản web không tự truy cập máy của bạn.');}catch(e){note(e.message);}
   $('#skin-research-run').disabled=!runtime||!preview;$('#skin-research-run').onclick=run;$('#skin-research-export').onclick=()=>{if(result)downloadBlob(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),'luma-skin-research.json');};
  },()=>{mounted=false;controller?.abort();});
 }
 return{open};
}
